        vm.assume(actor != address(c) && actor != address(this) && actor != address(0));
        jump = bound(jump, 1, 100);
        // target block is a future block, so blockhash(target) == bytes32(0)
        // answer = keccak256(abi.encodePacked(bytes32(0))), a known constant
        bytes32 h = keccak256(abi.encodePacked(bytes32(0)));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);
        vm.roll(block.number + 1 + jump);
        vm.prank(actor);
        c.settle();
        assertTrue(address(c).balance == 3 ether);
    }
}

