// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(address actor, uint256 delay) public {
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        delay = bound(delay, 1, 256);

        // The target block recorded by lockInGuess is block.number + 1, which has not been
        // mined yet, so blockhash(target) is bytes32(0) for every admissible input; the
        // winning guess is therefore fully determined.  Compute it the same way the
        // contract will (the opcode agrees between test and contract context).
        uint256 target = block.number + 1;
        bytes32 h = keccak256(abi.encodePacked(blockhash(target)));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        vm.roll(target + delay); // any delay past the target block is admissible
        vm.prank(actor);
        c.settle(); // reference pays 2 ether for the matching stored guess

        assertTrue(address(c).balance == 1 ether);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g) public {
        // keep params in admissible domain (wide): actor must be a plain EOA that can receive ether
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);

        uint256 lockBlock = block.number;

        // actor locks in the fuzzed guess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // move past the target block so settle is admissible
        uint256 target = lockBlock + 1;
        vm.roll(target + 1);

        // the answer the REFERENCE contract must use: hash of the target block's hash
        bytes32 answer = keccak256(abi.encodePacked(blockhash(target)));
        bool shouldWin = (g == answer);

        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        c.settle();
        uint256 balAfter = address(c).balance;

        // general rule: payout of 2 ether happens iff the guess matched the hash of the locked target block
        assertTrue((balBefore - balAfter == 2 ether) == shouldWin);
    }
}
